(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');if(!('IntersectionObserver'in window))return;const active=new Map(),seen=new WeakSet();const nodes=[...document.querySelectorAll('main h1,main h2,main h3,main h4,main p,main li,main blockquote,main figure,main img,main .actions,main .plan-card,main .compare-row,main .closing-card,main summary,main table,main dl,main .button')].filter(e=>!e.closest('dialog'));const run=(el,inside)=>{active.get(el)?.cancel();if(reduced.matches)return;const big=el.matches('.plan-card,.compare-row,.closing-card,figure'),from=inside?{opacity:big ? 0.92 : 0.76,translate:'0 14px'}:{opacity:1,translate:'0 0'},to=inside?{opacity:1,translate:'0 0'}:{opacity:.9,translate:'0 -8px'};const animation=el.animate([from,to],{duration:inside?440:180,easing:'cubic-bezier(.2,.7,.2,1)',delay:inside?(nodes.indexOf(el)%3)*30:0});active.set(el,animation);animation.onfinish=()=>active.delete(el);};const ob=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){if(!e.target.checkVisibility?.()&&e.target.checkVisibility)return;seen.add(e.target);e.target.dataset.motionState='in';run(e.target,true);}else if(seen.has(e.target)){e.target.dataset.motionState='out';run(e.target,false);}}),{threshold:0,rootMargin:'-12px 0px -12px 0px'});nodes.forEach(e=>ob.observe(e));const clear=()=>{active.forEach(a=>a.cancel());active.clear();};reduced.addEventListener('change',clear);addEventListener('beforeprint',clear);})();
